#!/usr/bin/env bash
# Builds an optimized release binary at ./app.
set -euo pipefail
cd "$(dirname "$0")"

command -v go >/dev/null || { echo "go is required" >&2; exit 1; }

CGO_ENABLED=0 go build -trimpath -ldflags="-s -w" -o app .

// Package server implements the kvhttp HTTP API on top of a store.Store.
package server

import (
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"regexp"
	"strconv"
	"strings"

	"kvhttp/internal/store"
)

// MaxValueBytes is the largest value accepted by PUT /kv/<key>.
const MaxValueBytes = 1 << 20

const kvPrefix = "/kv/"

var keyPattern = regexp.MustCompile(`^[A-Za-z0-9_-]{1,64}$`)

// Handler serves the kvhttp routes.
type Handler struct {
	store *store.Store
}

// New returns a Handler backed by s.
func New(s *store.Store) *Handler {
	return &Handler{store: s}
}

// ServeHTTP routes on the raw (undecoded, uncleaned) request path so that
// percent-encoded or dot-segment keys are rejected rather than reinterpreted.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path, _, _ := strings.Cut(r.URL.EscapedPath(), "?")

	switch {
	case path == "/health":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		send(w, http.StatusOK, []byte("ok"), "text/plain; charset=utf-8")

	case path == "/kv":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		body, err := json.Marshal(h.store.Keys())
		if err != nil {
			log.Printf("encode keys: %v", err)
			send(w, http.StatusInternalServerError, nil, "")
			return
		}
		send(w, http.StatusOK, body, "application/json")

	case strings.HasPrefix(path, kvPrefix):
		key := path[len(kvPrefix):]
		if !keyPattern.MatchString(key) {
			send(w, http.StatusBadRequest, nil, "")
			return
		}
		h.serveKey(w, r, key)

	default:
		send(w, http.StatusNotFound, nil, "")
	}
}

func (h *Handler) serveKey(w http.ResponseWriter, r *http.Request, key string) {
	switch r.Method {
	case http.MethodGet:
		value, ok := h.store.Get(key)
		if !ok {
			send(w, http.StatusNotFound, nil, "")
			return
		}
		send(w, http.StatusOK, value, "application/octet-stream")

	case http.MethodPut:
		value, err := readBody(w, r)
		if err != nil {
			var tooLarge *http.MaxBytesError
			status := http.StatusBadRequest
			if errors.As(err, &tooLarge) {
				status = http.StatusRequestEntityTooLarge
			}
			w.Header().Set("Connection", "close")
			send(w, status, nil, "")
			return
		}
		status := http.StatusOK
		if h.store.Set(key, value) {
			status = http.StatusCreated
		}
		send(w, status, nil, "")

	case http.MethodDelete:
		status := http.StatusNotFound
		if h.store.Delete(key) {
			status = http.StatusNoContent
		}
		send(w, status, nil, "")

	default:
		methodNotAllowed(w, http.MethodGet, http.MethodPut, http.MethodDelete)
	}
}

func readBody(w http.ResponseWriter, r *http.Request) ([]byte, error) {
	if r.ContentLength > MaxValueBytes {
		return nil, &http.MaxBytesError{Limit: MaxValueBytes}
	}
	return io.ReadAll(http.MaxBytesReader(w, r.Body, MaxValueBytes))
}

func methodNotAllowed(w http.ResponseWriter, allowed ...string) {
	w.Header().Set("Allow", strings.Join(allowed, ", "))
	send(w, http.StatusMethodNotAllowed, nil, "")
}

func send(w http.ResponseWriter, status int, body []byte, contentType string) {
	hdr := w.Header()
	if contentType != "" {
		hdr.Set("Content-Type", contentType)
	}
	hdr.Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	if len(body) > 0 {
		if _, err := w.Write(body); err != nil {
			log.Printf("write response: %v", err)
		}
	}
}

package server

import (
	"bytes"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"kvhttp/internal/store"
)

func do(t *testing.T, h http.Handler, method, target string, body []byte) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(method, target, bytes.NewReader(body))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

func TestRoutes(t *testing.T) {
	h := New(store.New())
	long := strings.Repeat("a", 65)

	steps := []struct {
		method, path, body string
		status             int
		want               string
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/health", "", 405, ""},
		{"GET", "/kv", "", 200, "[]"},
		{"PUT", "/kv/b", "2", 201, ""},
		{"PUT", "/kv/a", "1", 201, ""},
		{"PUT", "/kv/a", "one", 200, ""},
		{"GET", "/kv/a", "", 200, "one"},
		{"PUT", "/kv/empty", "", 201, ""},
		{"GET", "/kv/empty", "", 200, ""},
		{"GET", "/kv", "", 200, `["a","b","empty"]`},
		{"POST", "/kv", "", 405, ""},
		{"DELETE", "/kv/a", "", 204, ""},
		{"DELETE", "/kv/a", "", 404, ""},
		{"GET", "/kv/a", "", 404, ""},
		{"PATCH", "/kv/a", "", 405, ""},
		{"GET", "/kv/", "", 400, ""},
		{"GET", "/kv/a/b", "", 400, ""},
		{"GET", "/kv/bad.key", "", 400, ""},
		{"GET", "/kv/%41", "", 400, ""},
		{"GET", "/kv/" + long, "", 400, ""},
		{"GET", "/nope", "", 404, ""},
		{"GET", "/", "", 404, ""},
	}
	for _, s := range steps {
		rec := do(t, h, s.method, s.path, []byte(s.body))
		if rec.Code != s.status {
			t.Errorf("%s %s: status %d, want %d", s.method, s.path, rec.Code, s.status)
		}
		if got := rec.Body.String(); got != s.want {
			t.Errorf("%s %s: body %q, want %q", s.method, s.path, got, s.want)
		}
	}
}

func TestValueLimit(t *testing.T) {
	h := New(store.New())
	if rec := do(t, h, "PUT", "/kv/k", make([]byte, MaxValueBytes)); rec.Code != 201 {
		t.Fatalf("max-size value: status %d", rec.Code)
	}
	if rec := do(t, h, "PUT", "/kv/k2", make([]byte, MaxValueBytes+1)); rec.Code != 413 {
		t.Fatalf("oversize value: status %d", rec.Code)
	}
}

// Package store provides a concurrency-safe in-memory key-value store.
package store

import (
	"slices"
	"sync"
)

// Store maps string keys to raw byte values. The zero value is ready to use.
type Store struct {
	mu      sync.RWMutex
	entries map[string][]byte
}

// New returns an empty Store.
func New() *Store {
	return &Store{entries: make(map[string][]byte)}
}

// Set stores value under key and reports whether the key was newly created.
// The store takes ownership of value; callers must not modify it afterwards.
func (s *Store) Set(key string, value []byte) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.entries == nil {
		s.entries = make(map[string][]byte)
	}
	_, exists := s.entries[key]
	s.entries[key] = value
	return !exists
}

// Get returns the value stored under key and whether it was present.
// The returned slice must not be modified.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.entries[key]
	return v, ok
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.entries[key]
	delete(s.entries, key)
	return ok
}

// Keys returns all keys in ascending order. It never returns nil.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := make([]string, 0, len(s.entries))
	for k := range s.entries {
		keys = append(keys, k)
	}
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}

// Command app runs the kvhttp in-memory key-value HTTP server.
//
// Usage: app <port>
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"kvhttp/internal/server"
	"kvhttp/internal/store"
)

func main() {
	log.SetFlags(0)
	if len(os.Args) != 2 {
		usage()
	}
	port, err := strconv.Atoi(os.Args[1])
	if err != nil || port < 1 || port > 65535 {
		usage()
	}
	if err := run(port); err != nil {
		log.Fatalf("server error: %v", err)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: app <port>")
	os.Exit(2)
}

func run(port int) error {
	addr := net.JoinHostPort("127.0.0.1", strconv.Itoa(port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return err
	}

	srv := &http.Server{
		Handler:           server.New(store.New()),
		ReadHeaderTimeout: 10 * time.Second,
		IdleTimeout:       5 * time.Second,
		ErrorLog:          log.Default(),
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()
	log.Printf("kvhttp listening on %s", addr)

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil && !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}
